import coverage from "@/data/ats-coverage.json";

export const metadata = {
  title: "Which application systems Zapply supports",
  description:
    "Every applicant tracking system Zapply recognises, and exactly how much of that support is covered by tests.",
};

/**
 * The public coverage page.
 *
 * Generated by `scripts/build-coverage.mjs` from the adapters that exist and the
 * fixtures that run, and guarded by `test/coverage.spec.mjs`. Nothing on this
 * page is written by hand, which is the point: a support list maintained by hand
 * is correct on the day it is written and drifts every day afterwards, and the
 * drift always runs in the flattering direction.
 *
 * The three tiers are stated plainly rather than blurred into one "supported"
 * badge. Every competitor claims a long list of systems; being the one that says
 * which parts of its own list are actually tested is worth more than adding
 * another name to it.
 */

const TIERS = {
  verified: {
    label: "Verified",
    blurb: "A real form from this system is replayed by our test suite on every change.",
    dot: "bg-accent",
  },
  detected: {
    label: "Recognised",
    blurb:
      "Zapply knows this system and how to find its forms, but we have not captured one for the test suite yet — so nothing guards it against regressions.",
    dot: "bg-warn",
  },
};

export default function CoveragePage() {
  const verified = coverage.rows.filter((r) => r.tier === "verified");
  const detected = coverage.rows.filter((r) => r.tier === "detected");

  return (
    <main className="mx-auto max-w-3xl px-5 py-14">
      <h1 className="text-3xl font-semibold tracking-tight text-ink">Application systems we support</h1>
      <p className="mt-3 text-[15px] leading-relaxed text-ink-soft">
        Zapply recognises {coverage.totals.adapters} applicant tracking systems. Below is
        which ones are covered by automated tests and which are not. We publish both,
        because a list that does not separate them is not telling you anything.
      </p>

      <dl className="mt-7 grid grid-cols-3 gap-3">
        <Stat value={String(coverage.totals.adapters)} label="systems recognised" />
        <Stat value={String(coverage.totals.verified)} label="covered by tests" />
        <Stat value={String(coverage.totals.assertions)} label="field assertions" />
      </dl>

      <Section
        tier="verified"
        rows={verified}
        empty="No system is test-covered yet. Capture a form with the extension to add one."
      />
      <Section tier="detected" rows={detected} empty="Every recognised system is covered." />

      <section className="mt-10 rounded-xl border border-line bg-surface p-5">
        <h2 className="text-[15px] font-semibold text-ink">Anything else</h2>
        <p className="mt-1.5 text-[14px] leading-relaxed text-ink-soft">
          On a system not listed here, Zapply falls back to reading the form itself —
          labels, field types and structure — rather than giving up. That works on a
          great many career sites. It is simply not something we can promise, so we do
          not list it as support.
        </p>
      </section>

      <p className="mt-8 text-[12.5px] text-ink-faint">
        Generated from the codebase on{" "}
        {new Date(coverage.generatedAt).toLocaleDateString("en-GB", {
          day: "numeric",
          month: "long",
          year: "numeric",
        })}
        . Not hand-maintained.
      </p>
    </main>
  );
}

function Stat({ value, label }: { value: string; label: string }) {
  return (
    <div className="rounded-xl border border-line bg-surface p-4">
      <dt className="text-2xl font-semibold text-ink">{value}</dt>
      <dd className="mt-0.5 text-[12.5px] text-ink-faint">{label}</dd>
    </div>
  );
}

function Section({
  tier,
  rows,
  empty,
}: {
  tier: keyof typeof TIERS;
  rows: typeof coverage.rows;
  empty: string;
}) {
  const meta = TIERS[tier];
  return (
    <section className="mt-9">
      <div className="flex items-center gap-2">
        <span className={`h-2 w-2 rounded-full ${meta.dot}`} aria-hidden />
        <h2 className="text-[15px] font-semibold text-ink">
          {meta.label} <span className="font-normal text-ink-faint">({rows.length})</span>
        </h2>
      </div>
      <p className="mt-1 text-[13.5px] leading-relaxed text-ink-soft">{meta.blurb}</p>

      {rows.length === 0 ? (
        <p className="mt-3 text-[13.5px] text-ink-faint">{empty}</p>
      ) : (
        <ul className="mt-3 grid grid-cols-2 gap-x-4 gap-y-1.5 sm:grid-cols-3">
          {rows.map((row) => (
            <li key={row.key} className="flex items-baseline justify-between gap-2 text-[13.5px] text-ink">
              <span>{row.label}</span>
              {row.assertions > 0 && (
                <span className="text-[11.5px] tabular-nums text-ink-faint">{row.assertions}</span>
              )}
            </li>
          ))}
        </ul>
      )}
    </section>
  );
}
